+                <p class="product-copy">${product.description}</p>
+                <div class="product-bottom">
+                  <div class="price">$${product.price}</div>
+                  <button class="btn btn-primary add-to-bag" type="button" data-product="${product.name}">Add to bag</button>
+                </div>
+              </div>
+            </article>
+          `
+        )
+        .join("");
+    }
+
+    function renderCountdown() {
+      const countdown = document.getElementById("countdown");
+      const deadline = new Date();
+      deadline.setDate(deadline.getDate() + 3);
+      deadline.setHours(23, 59, 59, 999);
+
+      function update() {
+        const now = new Date();
+        const diff = Math.max(deadline - now, 0);
+        const totalSeconds = Math.floor(diff / 1000);
+        const days = Math.floor(totalSeconds / 86400);
+        const hours = Math.floor((totalSeconds % 86400) / 3600);
+        const minutes = Math.floor((totalSeconds % 3600) / 60);
+        const seconds = totalSeconds % 60;
+
+        const units = [
+          ["Days", days],
+          ["Hours", hours],
+          ["Minutes", minutes],
+          ["Seconds", seconds]
+        ];
+
+        countdown.innerHTML = units
+          .map(
+            ([label, value]) => `
+              <div class="time-box">
+                <strong>${String(value).padStart(2, "0")}</strong>
+                <span>${label}</span>
+              </div>
+            `
+          )
+          .join("");
+      }
+
+      update();
+      setInterval(update, 1000);
+    }
+
+    filtersContainer.addEventListener("click", (event) => {
+      const button = event.target.closest("[data-filter]");
+      if (!button) return;
+      activeFilter = button.dataset.filter;
+      renderFilters();
+      renderProducts();
+    });
+
+    productsContainer.addEventListener("click", (event) => {
+      const button = event.target.closest(".add-to-bag");
+      if (!button) return;
+      bagItems += 1;
+      cartCount.textContent = bagItems;
+      showToast(`${button.dataset.product} added to bag`);
+    });
+
+    newsletterForm.addEventListener("submit", (event) => {
+      event.preventDefault();
+      const email = document.getElementById("email");
+      showToast(`Subscribed: ${email.value}`);
+      newsletterForm.reset();
+    });
+
+    renderFilters();
+    renderProducts();
+    renderCountdown();
+  </script>
+</body>
+</html>
+

')

