              type="button"
              data-filter="${filter}"
              aria-pressed="${filter === activeFilter}">
              ${filter}
            </button>
          `
        )
        .join("");
    }

    function renderProducts() {
      const visibleProducts = activeFilter === "All"
        ? products
        : products.filter((product) => product.category === activeFilter);

      productsContainer.innerHTML = visibleProducts
